#include <iostream>
using namespace std;

struct Edge {
    int to;
    Edge* next;
};

const int V = 4;

void addEdge(Edge* adj[], int u, int v) {
    Edge* e = new Edge();
    e->to = v;
    e->next = adj[u];
    adj[u] = e;
}

int main() {
    Edge* adj[V];
    for (int i = 0; i < V; i++) {
        adj[i] = nullptr;
    }
    addEdge(adj, 0, 1);
    addEdge(adj, 1, 0);
    addEdge(adj, 0, 2);
    addEdge(adj, 2, 0);
    addEdge(adj, 2, 3);
    addEdge(adj, 3, 2);
    for (Edge* e = adj[0]; e != nullptr; e = e->next) {
        cout << "0 -> " << e->to << endl;
    }
    for (int i = 0; i < V; i++) {
        while (adj[i] != nullptr) {
            Edge* old = adj[i];
            adj[i] = adj[i]->next;
            delete old;
        }
    }
    return 0;
}
